{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리에 적절한 개선 방법을 적용할 수 있는지 확인한다. 신고 목록 조회 쿼리에 인덱스를 추가한 판단 근거에 초점을 맞춘다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인 순서를 정리해 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 내용과 조회 조건을 연결해 인덱스를 추가한 근거를 설명한다.",
          "result": "전체 개선 결과와 구분해 인덱스가 조회 비용을 줄일 것으로 판단한 근거를 설명한다."
        },
        "expectedEvidence": [
          "조회 조건에 맞는 인덱스를 추가한 구체적인 판단 근거",
          "그 판단을 뒷받침한 실행 계획의 내용",
          "조회 조건과 인덱스가 데이터 탐색 범위를 줄이는 방식의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 조회 조건에 맞는 인덱스를 추가하신 근거는 무엇이었나요?",
      "answerTip": "가장 전하고 싶은 내용부터 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 조회 비용이나 데이터 접근 방식에 근거해 인덱스를 추가한 판단을 구체적으로 설명한다.",
            "조회 조건과 추가한 인덱스를 연결해 불필요한 데이터 탐색을 줄일 수 있었던 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 조건이나 실행 계획을 근거로 인덱스를 추가했다고 답하지만 확인한 내용은 포괄적이다.",
            "인덱스가 조회를 빠르게 한다는 설명은 타당하지만 해당 쿼리의 데이터 탐색 방식과 연결하는 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가한 판단 근거를 제시하지 않고 개선 수치나 작업 목록만 반복한다.",
            "조회 조건과 무관한 일반론을 말하거나 인덱스가 조회 비용을 줄이는 원리를 잘못 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 복구 조치를 실제로 적용할 수 있는지 확인한다. 두 서버에서 발생한 스케줄러 중복 실행을 잠금 키로 막은 방식에 초점을 맞춘다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔고, 시간순으로 모은 로그에서 두 서버의 스케줄러가 동시에 실행되는 것을 확인했다.",
          "task": "잠금 키를 두는 방식으로 스케줄러 중복 실행 오류를 수정했다.",
          "action": "잠금 키가 두 서버의 스케줄러 실행을 제어한 구체적인 방식을 설명한다.",
          "result": "설명한 잠금 방식에서 같은 작업이 중복 실행되지 않게 되는 동작을 설명한다."
        },
        "expectedEvidence": [
          "잠금 키로 스케줄러 중복 실행을 막은 구체적인 방식",
          "두 서버가 같은 작업의 잠금을 확인하거나 획득하는 동작",
          "잠금 획득 여부에 따라 스케줄러 실행이 달라지는 동작"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 고치셨을 때, 잠금 키로 스케줄러 중복 실행을 막은 방식은 무엇이었나요?",
      "answerTip": "듣는 사람이 떠올릴 수 있게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "두 서버가 같은 작업의 잠금을 공유하는 방식과 잠금 획득 여부에 따른 실행 동작을 구체적으로 설명한다.",
            "동시에 실행을 시도하더라도 하나의 실행만 허용되는 타당한 잠금 방식을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금을 얻은 경우에만 스케줄러를 실행한다는 방식을 답하지만 두 서버 사이에서 잠금을 다루는 설명은 부족하다.",
            "중복 실행을 막는 방향은 타당하지만 동시 실행 시 잠금이 작동하는 설명은 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 추가했다는 말만 반복하거나 로그로 원인을 찾은 이야기만 하고 실제 실행 제어 방식을 답하지 않는다.",
            "서버마다 독립된 잠금만 두는 등 두 서버의 동시 실행을 막을 수 없는 방식을 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청을 개발·디자인 담당자가 구현 범위를 이해할 수 있는 요구사항 문서로 구체화하는 능력을 확인한다. 요구사항 정의서에 개발할 범위를 실제로 적은 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "요구사항 정의서에 개발할 범위를 적은 실제 내용을 설명한다.",
          "result": "설명한 문서 내용에서 구현할 기능과 범위의 경계가 얼마나 명확하게 드러나는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항 정의서에 개발할 범위를 적은 실제 내용",
          "포함·제외 항목이나 적용 조건 등 범위의 경계를 보여주는 문서 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨을 때, 개발할 범위를 문서에 어떤 내용으로 적으셨나요?",
      "answerTip": "직접 했던 내용을 중심으로 짧게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항 정의서에 적은 기능과 적용 범위를 실제 문서 내용을 알아볼 수 있을 만큼 구체적으로 답한다.",
            "포함·제외 항목이나 적용 조건 등으로 범위의 경계를 밝혀 개발·디자인 담당자가 구현 대상을 구분할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "문서에 적은 개발 대상 기능을 답하지만 구체적인 동작이나 적용 범위 설명이 일부 빠져 있다.",
            "범위의 경계가 일부 드러나지만 무엇까지 구현하는지 추가로 확인해야 한다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰를 했거나 문서를 작성했다는 사실만 말하고 문서에 적은 개발 범위를 답하지 않는다.",
            "기능명이나 요청을 나열하는 데 그쳐 구현할 범위를 구분할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서 화면이 보일 상태와 동작을 구현 가능한 수준으로 설계하는 능력을 확인한다. 실제 화면설계서 한 장에 예외 상황을 구체적으로 담은 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 Figma로 작성했다.",
          "task": "기획 담당으로 화면설계서를 작성했다.",
          "action": "예외 상황을 담은 화면 한 장을 골라 해당 화면에 실제로 적은 설계 내용을 설명한다.",
          "result": "설명한 설계 내용에서 예외 상황의 화면 상태와 사용자가 할 수 있는 동작이 얼마나 명확하게 드러나는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황을 담은 화면 한 장의 실제 설계 내용",
          "해당 예외가 발생하는 조건과 그때 보이는 화면 상태",
          "해당 화면에 명시한 안내 문구나 사용자 조작에 따른 동작"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 Figma로 화면설계서 28장을 작성하셨을 때, 예외 상황을 담은 화면 한 장의 설계 내용은 무엇이었나요?",
      "answerTip": "기억나는 장면을 떠올려 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 설계한 화면 한 장에서 어떤 예외 조건에 어떤 화면 상태를 표시했는지 구체적으로 답한다.",
            "안내 문구나 사용자 조작에 따른 동작을 명확히 설명해 개발·디자인 담당자가 해당 예외 화면을 구현할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 담은 화면의 설계 내용을 답하지만 발생 조건이나 화면 상태가 일부 불명확하다.",
            "안내 문구나 화면 동작을 설명하지만 구현하려면 세부 내용을 추가로 확인해야 한다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서의 분량이나 사용 도구만 말하고 예외 화면의 실제 설계 내용을 답하지 않는다.",
            "예외를 고려해야 한다는 일반론이나 정상 흐름만 설명해 예외 상황에서 보일 화면을 알 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 확인할 수 있는지 평가한다. 실제 진통제 처방 사례에서 투약을 보류하고 담당의에게 확인한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 맡았다.",
          "action": "처방 용량의 차이를 의심 신호로 받아들여 투약을 멈추고 담당의에게 확인한 판단 근거를 설명한다.",
          "result": "담당의에게 확인한 결과 입력 오류였다는 사실을 자신의 판단 근거와 연결해 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 한 판단 근거",
          "판단의 근거로 삼은 평소 용량과 해당 처방 용량의 차이"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인한 판단 근거는 무엇이었나요?",
      "answerTip": "본인이 했던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 해당 처방 용량의 차이를 구체적으로 짚어 처방을 의심한 근거를 설명한다.",
            "처방의 정확성을 확인하지 않은 상태에서는 투약하지 않겠다는 판단을 해당 사례에 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량이 평소와 달라 투약을 멈추고 확인했다고 답하지만 비교한 내용을 구체적으로 설명하지 않는다.",
            "확인이 필요하다는 판단은 드러나지만 해당 처방을 그대로 수행하지 않은 근거는 일반적인 안전 원칙 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추고 담당의에게 확인한 판단 근거를 제시하지 못한다.",
            "용량 차이와 처방 확인의 필요성을 연결하지 못하고 투약 절차에 관한 일반론만 말한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태와 그 변화를 간호 기록에 정확히 남길 수 있는지 평가한다. 실제 활력징후와 통증 관찰 경험에서 기록에 남긴 내용의 구체성과 정확성에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하고 기록했다.",
          "task": "활력징후와 통증 관찰 기록을 맡았다.",
          "action": "관찰한 활력징후와 통증을 간호 기록에 실제로 어떤 내용으로 남겼는지 설명한다.",
          "result": "제시한 기록 내용이 관찰 당시 환자 상태나 이전 관찰과의 차이를 어떻게 드러냈는지 설명한다."
        },
        "expectedEvidence": [
          "활력징후와 통증을 관찰해 간호 기록에 실제로 남긴 내용",
          "기록 내용에 담긴 관찰 시점과 환자 상태를 나타내는 구체적인 정보"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 활력징후와 통증을 관찰해 기록하셨을 때, 관찰한 환자 상태를 간호 기록에 어떤 내용으로 남기셨나요?",
      "answerTip": "기억나는 내용을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
